```st
FUNCTION_BLOCK FB
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head_pos : DINT := 1;
    enqueue_prev : BOOL := FALSE;
    dequeue_prev : BOOL := FALSE;
END_VAR

    // Reset takes priority
    IF reset THEN
        elementCount := 0;
        status := 16#0000;
        head_pos := 1;
    ELSIF enqueue AND NOT enqueue_prev THEN
        // Rising edge on enqueue
        IF elementCount < capacity THEN
            buffer[((head_pos + elementCount - 1) MOD capacity) + 1] := item;
            elementCount := elementCount + 1;
            status := 16#0000;
        ELSE
            status := 16#8002;
        END_IF;
    ELSIF dequeue AND NOT dequeue_prev THEN
        // Rising edge on dequeue
        IF elementCount > 0 THEN
            item := buffer[head_pos];
            head_pos := (head_pos MOD capacity) + 1;
            elementCount := elementCount - 1;
            status := 16#0000;
        ELSE
            status := 16#8001;
        END_IF;
    ELSE
        status := 16#0000;
    END_IF;

    enqueue_prev := enqueue;
    dequeue_prev := dequeue;

END_FUNCTION_BLOCK
```

